<?php
namespace App\Controllers; use App\AI\AIManager; use App\Middleware\Auth; final class ApiController { public function ai(){ Auth::requireUser(); \verify_csrf(); try { $type=$_POST['type'] ?? 'summary_generator'; $vars=['task'=>$type,'name'=>Auth::user()['name'],'job_title'=>$_POST['job_title']??'','experience'=>$_POST['experience']??'','skills'=>$_POST['skills']??'','education'=>$_POST['education']??'','job_description'=>$_POST['job_description']??'']; $res=(new AIManager)->run($type,$vars); \json_response(['success'=>true,'message'=>'Generated successfully','data'=>['content'=>$res['text']]]); } catch(\Throwable $e){ \app_log('AI request failed',['error'=>$e->getMessage()]); \json_response(['success'=>false,'message'=>'Something went wrong. Please try again.'],500); } } }
